// The one TUI piece the tool touches. The renderers keep the same component
// across repaints and read it back out, so setText and the stored text are the
// whole contract; the harness reads `.content` to assert what the panel said.
export class Text {
  constructor(content = "") {
    this.content = String(content ?? "");
  }

  setText(content) {
    this.content = String(content ?? "");
  }

  toString() {
    return this.content;
  }
}
